def apply(inputs, premises):
    spans = inputs.get("source_spans") or []
    query = inputs.get("query") or {}
    focus = inputs.get("focus_unit_id")
    if focus is None:
        focus = query.get("focus_unit_id")
    current = []
    for span in spans:
        if isinstance(span, dict) and "id" in span:
            current.append(span["id"])
    selected = set()
    for unit_id in query.get("unit_ids") or []:
        if unit_id in current:
            selected.add(unit_id)
    if focus in current:
        selected.add(focus)
        index = current.index(focus)
        left = max(0, index - 2)
        for position in range(left, index + 1):
            selected.add(current[position])
    return {"unit_ids": [unit_id for unit_id in current if unit_id in selected]}

